<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require dirname(__DIR__).'/lib/rakuten_api.php';require dirname(__DIR__).'/lib/repository.php';function import_lock(){ $d=dirname(__DIR__).'/storage/locks';if(!is_dir($d)&&!@mkdir($d,0775,true)&&!is_dir($d))throw new RuntimeException('cronロック用ディレクトリを作成できません');$h=@fopen($d.'/rakuten-import.lock','c');if(!is_resource($h))throw new RuntimeException('cronロックファイルを開けません');if(!@flock($h,LOCK_EX|LOCK_NB)){fclose($h);return null;}return $h;}$lock=import_lock();if(!is_resource($lock)){echo "import skipped: another process is running\n";exit(0);}register_shutdown_function(static function()use($lock){@flock($lock,LOCK_UN);fclose($lock);});$pdo=db();$base=(array)app_config('rakuten',[]);$cfg=$base;foreach(['application_id','access_key','affiliate_id'] as $k)$cfg[$k]=setting($pdo,'rakuten_'.$k,(string)($base[$k]??''));$cfg['hits']=max(1,min(30,(int)setting($pdo,'rakuten_hits',(string)($base['hits']??30))));$cfg['sort']=setting($pdo,'rakuten_sort',(string)($base['sort']??'-reviewCount'));foreach(['application_id','access_key'] as $r)if(empty($cfg[$r])){fwrite(STDERR,"Rakuten API設定不足: {$r}\n");exit(1);}$client=new RakutenApiClient($cfg);$jobs=[];$cats=$pdo->query('SELECT * FROM categories WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();foreach($cats as $c){$keywords=array_values(array_filter(array_map('trim',preg_split('/\R/u',(string)$c['keywords'])?:[])));if(!$keywords)$keywords=[''];foreach($keywords as $kw)$jobs[]=['category'=>(int)$c['id'],'genre'=>(int)$c['rakuten_genre_id'],'keyword'=>$kw,'ng'=>(string)$c['ng_keywords']];}if(!$jobs){$keywordText=setting($pdo,'rakuten_keywords',implode("\n",(array)($base['keywords']??[])));foreach(array_filter(array_map('trim',preg_split('/\R/u',$keywordText)?:[])) as $kw)$jobs[]=['category'=>0,'genre'=>0,'keyword'=>$kw,'ng'=>setting($pdo,'rakuten_ng_keywords','')];}if($jobs){$cursor=max(0,(int)setting($pdo,'rakuten_import_cursor','0'))%count($jobs);$max=min(3,count($jobs));for($n=0;$n<$max;$n++){$j=$jobs[($cursor+$n)%count($jobs)];try{$data=$client->search($j['keyword'],1,$j['genre']>0?$j['genre']:null,$j['ng']);$items=(array)($data['items']??[]);$pdo->beginTransaction();foreach($items as $item){if(!is_array($item))continue;$id=save_item($pdo,$item);if($j['category']>0&&$id>0)$pdo->prepare('INSERT IGNORE INTO item_categories(item_id,category_id) VALUES(?,?)')->execute([$id,$j['category']]);}$pdo->prepare("INSERT INTO import_logs(keyword,page_no,fetched_count,status,message) VALUES(?,1,?,'success',NULL)")->execute([$j['keyword']?:('genre:'.$j['genre']),count($items)]);$pdo->commit();echo date('Y-m-d H:i:s').' imported='.count($items).PHP_EOL;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$pdo->prepare("INSERT INTO import_logs(keyword,page_no,fetched_count,status,message) VALUES(?,1,0,'error',?)")->execute([$j['keyword']?:('genre:'.$j['genre']),mb_substr($e->getMessage(),0,1000)]);fwrite(STDERR,$e->getMessage().PHP_EOL);}if($n+1<$max)sleep(1);}save_setting($pdo,'rakuten_import_cursor',(string)(($cursor+$max)%count($jobs)));}try{$rank=$client->ranking(null,1);$rows=(array)($rank['Items']??$rank['items']??[]);$pdo->beginTransaction();$pdo->exec('DELETE FROM rakuten_rankings WHERE genre_id=0');$st=$pdo->prepare('INSERT INTO rakuten_rankings(genre_id,rank_no,item_code,item_name,item_price,item_url,affiliate_url,image_url,shop_name,review_count,review_average) VALUES(0,?,?,?,?,?,?,?,?,?,?)');foreach($rows as $row){$it=is_array($row)&&isset($row['Item'])?(array)$row['Item']:(array)$row;$imgs=normalize_image_urls($it);$st->execute([(int)($it['rank']??0),(string)($it['itemCode']??''),(string)($it['itemName']??''),(int)($it['itemPrice']??0),(string)($it['itemUrl']??''),(string)($it['affiliateUrl']??$it['itemUrl']??''),$imgs[0]??null,(string)($it['shopName']??''),(int)($it['reviewCount']??0),(float)($it['reviewAverage']??0)]);}$pdo->commit();echo 'ranking updated='.count($rows).PHP_EOL;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,'ranking: '.$e->getMessage().PHP_EOL);}foreach([['import_logs',90],['page_views',730],['affiliate_clicks',730]] as [$t,$d]){try{$pdo->exec("DELETE FROM {$t} WHERE created_at<DATE_SUB(NOW(),INTERVAL {$d} DAY) LIMIT 500");}catch(Throwable $e){error_log($e->getMessage());}}
